begin;
select plan(10);
select ok((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception' and pg_get_function_identity_arguments(p.oid)='p_cod_receipt_id uuid, p_reason text, p_idempotency_key text'),'Admin COD exception resolution command exists with expected signature');
select ok((select p.prosecdef and p.proconfig @> array['search_path=pg_catalog, public'] from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'resolution uses SECURITY DEFINER and controlled search_path');
select ok((select position('public.app_role() <> ''admin''' in pg_get_functiondef(p.oid))>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'resolution is Admin-only');
select ok((select position('v_receipt.state <> ''Exception''' in pg_get_functiondef(p.oid))>0 and position('Only COD receipts in Exception state can be resolved' in pg_get_functiondef(p.oid))>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'only Exception-state receipts are eligible');
select ok((select position('v_receipt.received_amount - v_receipt.expected_amount_snapshot' in pg_get_functiondef(p.oid))>0 and position('COD_EXCEPTION_RESOLUTION' in pg_get_functiondef(p.oid))>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'resolution creates append-only adjustment equal to collected minus expected');
select ok((select position('public.financial_adjustments' in pg_get_functiondef(p.oid))>0 and position('cod_receipt_id' in pg_get_functiondef(p.oid))>0 and position('parcel_id' in pg_get_functiondef(p.oid))>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'resolution adjustment retains receipt and parcel lineage');
select ok((select position('CodExceptionResolved' in pg_get_functiondef(p.oid))>0 and position('resolve_cod_exception' in pg_get_functiondef(p.oid))>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'resolution records permanent domain and audit evidence');
select ok((select position('claim_command_idempotency' in pg_get_functiondef(p.oid))>0 and position('complete_command_idempotency' in pg_get_functiondef(p.oid))>0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='resolve_cod_exception'),'resolution is retry-safe through command idempotency');
select ok((select count(*)=1 from pg_indexes where schemaname='public' and indexname='uq_financial_adjustments_cod_exception_resolution' and indexdef ilike '%unique%' and indexdef ilike '%cod_receipt_id%'),'a receipt has at most one COD exception resolution adjustment');
select ok((select not has_function_privilege('public','public.resolve_cod_exception(uuid,text,text)','execute') and not has_function_privilege('anon','public.resolve_cod_exception(uuid,text,text)','execute') and has_function_privilege('authenticated','public.resolve_cod_exception(uuid,text,text)','execute')),'resolution command is exposed only to authenticated callers');
select * from finish();
rollback;
